import os
import smtplib
from email.message import EmailMessage
import requests
import stripe
stripe.api_key = os.environ.get('STRIPE_API_KEY', '')
SMTP_HOST = os.environ.get('SMTP_HOST', 'localhost')
SMTP_PORT = int(os.environ.get('SMTP_PORT', '25'))
SENDER_ADDRESS = 'billing@learnhub.example'
LMS_API_URL = os.environ.get('LMS_API_URL', 'http://localhost:8080')
LMS_API_TOKEN = os.environ.get('LMS_API_TOKEN', '')

def refund_course_enrollment_and_notify(payment_intent_id: str, student_email: str, course_title: str, amount_cents: int=None) -> dict:
    if not payment_intent_id or not payment_intent_id.startswith('pi_'):
        return {'success': False, 'error': 'Invalid payment intent ID'}
    if '@' not in student_email or ' ' in student_email:
        return {'success': False, 'error': 'Invalid student email'}
    if not course_title.strip():
        return {'success': False, 'error': 'Course title is required'}
    if amount_cents is not None and amount_cents <= 0:
        return {'success': False, 'error': 'amount_cents must be positive'}
    if amount_cents is None:
        # Full refund: remove the student's access to the course in the LMS
        try:
            requests.delete(f'{LMS_API_URL}/courses/access', json={'student_email': student_email, 'course_title': course_title}, headers={'Authorization': f'Bearer {LMS_API_TOKEN}'}, timeout=10).raise_for_status()
        except requests.RequestException as access_error:
            return {'success': False, 'error': f'Failed to revoke course access: {access_error}'}
    refund_arguments = {'payment_intent': payment_intent_id}
    if amount_cents is not None:
        refund_arguments['amount'] = amount_cents
    try:
        refund = stripe.Refund.create(**refund_arguments)
    except stripe.error.StripeError as stripe_error:
        return {'success': False, 'error': str(stripe_error)}
    refunded_dollars = refund['amount'] / 100
    message = EmailMessage()
    message['From'] = SENDER_ADDRESS
    message['To'] = student_email
    message['Subject'] = f'Your refund for {course_title}'
    message.set_content(f"We have refunded ${refunded_dollars:.2f} for your enrollment in {course_title}. Refund reference: {refund['id']}.")
    try:
        with smtplib.SMTP(SMTP_HOST, SMTP_PORT) as smtp_server:
            smtp_server.send_message(message)
    except smtplib.SMTPException as email_error:
        return {'success': True, 'refund_id': refund['id'], 'email_sent': False, 'email_error': str(email_error)}
    return {'success': True, 'refund_id': refund['id'], 'email_sent': True}
